(()=>{
  'use strict';
  const q=(s,r=document)=>r.querySelector(s),qa=(s,r=document)=>[...r.querySelectorAll(s)];
  const PERMANENT=[
    ['plate_number','شماره پلاک'],['vehicle_type','نوع خودرو'],['body_color','رنگ بدنه'],['chassis_number','شماره شاسی'],
    ['handover_from','نام واحد/ شخص تحویل دهنده در زمان واگذاری به واحد'],['handover_to','نام شخص تحویل گیرنده در زمان واگذاری به واحد'],
    ['assignment_date','تاریخ واگذاری به واحد'],['current_location','محل استقرار فعلی'],
    ['documents_status','وضعیت مدارک(شامل بیمه بدنه، شخص ثالث، کارت خودرو و کارت سوخت)'],['remote_count','تعداد ریموت','number'],
    ['insurance_expiry_date','تاریخ انقضای بیمه'],['last_mileage','آخرین کیلومتر کارکرد','number'],['receipt_reason','علت دریافت خودرو'],
    ['return_receiver','نام واحد/ شخص تحویل گیرنده در زمان عودت از واحد'],['return_deliverer','نام شخص تحویل دهنده در زمان عودت از واحد'],
    ['return_date','تاریخ عودت از واحد'],['notes','توضیحات','textarea']
  ];
  const TEMPORARY=[
    ['plate_number','شماره پلاک'],['vehicle_type','نوع خودرو'],['body_color','رنگ بدنه'],['chassis_number','شماره شاسی'],
    ['handover_from','نام شخص تحویل دهنده در زمان واگذاری'],['handover_to','نام شخص تحویل گیرنده در زمان واگذاری'],
    ['assignment_date','تاریخ واگذاری'],['exit_time','ساعت خروج'],['entry_time','ساعت ورود'],['last_mileage','آخرین کیلومتر کارکرد','number'],
    ['fuel_status','وضعیت بنزین'],['receipt_reason','علت دریافت خودرو'],['notes','توضیحات','textarea']
  ];
  const CFG={
    vehiclePermanent:{view:'vehiclePermanentView',table:'vehicle_permanent_records',sheet:'تحویل و تحول دائم',title:'تحویل و تحول دائم',fields:PERMANENT,form:true},
    vehicleTemporary:{view:'vehicleTemporaryView',table:'vehicle_temporary_records',sheet:'تحویل تحول موقت',title:'تحویل و تحول موقت',fields:TEMPORARY,form:false}
  };
  const data={vehiclePermanent:{rows:[],selected:null,query:'',filters:{}},vehicleTemporary:{rows:[],selected:null,query:'',filters:{}}};
  let ready=false,editScope=null,editId=null,uploadScope=null;
  const esc=v=>typeof safe==='function'?safe(v):String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fan=v=>typeof fa==='function'?fa(v):String(v??'');
  const normalize=v=>String(v??'').replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/\u200c/g,' ').replace(/\s+/g,' ').trim();
  const selectedRow=scope=>data[scope].rows.find(r=>String(r.id)===String(data[scope].selected));
  const formLabel=row=>row?.form_path?decodeURIComponent(String(row.form_path).split('/').pop().replace(/^\d+-/,'')):'بارگذاری نشده';

  function addStyles(){
    if(q('#vehicleModuleStyles'))return;
    const s=document.createElement('style');s.id='vehicleModuleStyles';s.textContent=`
      #appView .vehicle-view{height:calc(100dvh - 58px - var(--footer-h,34px))!important;overflow:hidden!important;box-sizing:border-box!important}
      #appView .vehicle-view>.vehicle-panel{height:calc(100% - 8px)!important;display:flex!important;flex-direction:column!important;min-height:0!important;padding:28px 16px 16px!important;margin:4px 0!important;position:relative!important;border:1px solid #b8c8c1!important;background:#f8faf9!important;overflow:visible!important}
      #appView .vehicle-title{position:absolute!important;top:-15px!important;right:18px!important;margin:0!important;padding:0 10px!important;background:#eef3f0!important;color:#145741!important;font-size:18px!important;z-index:3!important}
      #appView .vehicle-toolbar{display:flex!important;align-items:center!important;gap:8px!important;direction:rtl!important;margin-bottom:10px!important;overflow-x:auto!important;padding:1px!important}
      #appView .vehicle-toolbar button,#appView .vehicle-toolbar a{flex:0 0 auto!important;min-height:38px!important;display:inline-flex!important;align-items:center!important;text-decoration:none!important}
      #appView .vehicle-toolbar .vehicle-search{width:250px!important;min-width:220px!important;height:38px!important;margin-right:auto!important}
      #appView .vehicle-table-wrap{flex:1 1 auto!important;min-height:0!important;overflow:auto!important;border:1px solid #b8c8c1!important;background:#fff!important}
      #appView .vehicle-data-table{width:max-content!important;min-width:100%!important;table-layout:fixed!important;border-collapse:collapse!important;direction:rtl!important;background:#fff!important}
      #appView .vehicle-data-table th{position:relative!important;background:#dfe9e4!important;color:#17362d!important;border:1px solid #b8c8c1!important;padding:9px 7px!important;text-align:center!important;white-space:normal!important;line-height:1.55!important}
      #appView .vehicle-data-table td{border:1px solid #d1ddd8!important;padding:8px!important;text-align:right!important;vertical-align:top!important;white-space:normal!important;overflow-wrap:anywhere!important;line-height:1.7!important}
      #appView .vehicle-data-table tr:nth-child(even) td{background:#fafcfa!important}#appView .vehicle-data-table tbody tr{cursor:pointer!important}
      #appView .vehicle-data-table tbody tr:hover td{background:#edf6f1!important}#appView .vehicle-data-table tr.vehicle-selected td{background:#dfeee7!important;outline:1px solid #4e917a!important;outline-offset:-1px!important}
      #appView .vehicle-data-table .vehicle-filters th{padding:5px!important;background:#edf3f0!important}#appView .vehicle-data-table .vehicle-filters select{width:100%!important;height:34px!important;direction:rtl!important;text-align:right!important;font-family:"B Nazanin",BNazanin,Tahoma,sans-serif!important}
      #appView .vehicle-data-table .vehicle-form-status{text-align:center!important;font-weight:700!important;color:#176b4d!important}
      #appView .vehicle-col-resize{position:absolute;inset-block:0;left:-5px;width:10px;cursor:col-resize;z-index:5}
      #vehicleRecordDialog{width:min(980px,95vw)!important}#vehicleRecordDialog .vehicle-form-grid{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:12px!important;max-height:65vh!important;overflow:auto!important;padding:2px!important}
      #vehicleRecordDialog label{display:flex!important;flex-direction:column!important;gap:5px!important;text-align:right!important}#vehicleRecordDialog label.wide{grid-column:1/-1!important}#vehicleRecordDialog input,#vehicleRecordDialog textarea{width:100%!important;box-sizing:border-box!important}#vehicleRecordDialog textarea{min-height:95px!important}
      @media(max-width:760px){#vehicleRecordDialog .vehicle-form-grid{grid-template-columns:1fr!important}#vehicleRecordDialog label.wide{grid-column:auto!important}#appView .vehicle-toolbar{flex-wrap:wrap!important}#appView .vehicle-toolbar .vehicle-search{order:20;width:100%!important;margin:0!important}}
    `;document.head.appendChild(s);
  }
  function toolbar(scope){const c=CFG[scope];return `<div class="vehicle-toolbar"><button class="primary vehicle-import" type="button">ورود از اکسل</button><button class="primary vehicle-add" type="button">افزودن</button><button class="ghost vehicle-edit" type="button" disabled>ویرایش</button><button class="danger vehicle-delete" type="button" disabled>حذف</button>${c.form?'<button class="ghost vehicle-upload" type="button" disabled>بارگذاری فرم</button><button class="ghost vehicle-download" type="button" disabled>دانلود فرم</button><a class="ghost vehicle-blank" href="vehicle-handover-blank.pdf" download="فرم خام تحویلی خودرو.pdf">دانلود فرم خام</a>':''}<input class="vehicle-search" type="search" placeholder="جست‌وجو در جدول..."></div>`}
  function mount(scope){const c=CFG[scope],view=q(`#${c.view}`);if(view)view.innerHTML=`<div class="panel vehicle-panel"><h3 class="vehicle-title">${esc(c.title)}</h3>${toolbar(scope)}<div class="vehicle-table-wrap"><table class="vehicle-data-table" data-scope="${scope}"><thead></thead><tbody></tbody></table></div></div>`}
  function ensureInputs(){
    if(q('#vehicleRecordDialog'))return;
    document.body.insertAdjacentHTML('beforeend',`<dialog id="vehicleRecordDialog" class="modal"><form id="vehicleRecordForm"><div class="modal-head"><div><h3 id="vehicleRecordTitle"></h3><p>فیلدها دقیقاً مطابق ستون‌های فایل اکسل هستند.</p></div><button type="button" data-vehicle-close>×</button></div><div id="vehicleRecordFields" class="vehicle-form-grid"></div><div class="modal-actions"><button class="ghost" type="button" data-vehicle-close>انصراف</button><button class="primary" type="submit">ثبت</button></div></form></dialog><input id="vehicleExcelInput" type="file" accept=".xlsx,.xls" hidden><input id="vehicleFormInput" type="file" accept="application/pdf,image/jpeg,image/png" hidden>`);
    qa('[data-vehicle-close]').forEach(b=>b.onclick=()=>q('#vehicleRecordDialog').close());q('#vehicleRecordForm').onsubmit=saveRecord;q('#vehicleExcelInput').onchange=importWorkbook;q('#vehicleFormInput').onchange=uploadForm;
  }
  function fieldHtml([key,label,type]){if(type==='textarea')return `<label class="wide">${esc(label)}<textarea name="${key}"></textarea></label>`;const inputType=type==='number'?'number':'text',placeholder=key.includes('date')?'۱۴۰۵/۰۱/۰۱':key.includes('time')?'۰۸:۳۰':'';return `<label>${esc(label)}<input name="${key}" type="${inputType}" ${placeholder?`placeholder="${placeholder}"`:''}></label>`}
  function openEditor(scope){const c=CFG[scope],row=selectedRow(scope);editScope=scope;editId=row?.id||null;q('#vehicleRecordTitle').textContent=row?`ویرایش ${c.title}`:`افزودن ${c.title}`;q('#vehicleRecordFields').innerHTML=c.fields.map(fieldHtml).join('');const form=q('#vehicleRecordForm');c.fields.forEach(([key])=>form.elements[key].value=row?.[key]??'');q('#vehicleRecordDialog').showModal()}
  function editorPayload(){const c=CFG[editScope],form=q('#vehicleRecordForm'),out={updated_at:new Date().toISOString()};c.fields.forEach(([key,,type])=>{let v=String(form.elements[key]?.value??'').trim();out[key]=type==='number'?(v===''?null:Number(v.replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)))):(v||null)});return out}
  async function saveRecord(e){e.preventDefault();try{const c=CFG[editScope],body=editorPayload();if(editId)await update(c.table,`id=eq.${encodeURIComponent(editId)}`,body);else await insert(c.table,body);q('#vehicleRecordDialog').close();toast(editId?'ردیف ویرایش شد.':'ردیف ثبت شد.');data[editScope].selected=null;await load(editScope)}catch(err){toast(err.message,true)}}
  async function load(scope){const c=CFG[scope];try{data[scope].rows=await select(c.table,'select=*&order=id.asc');if(!data[scope].rows.some(r=>String(r.id)===String(data[scope].selected)))data[scope].selected=null;render(scope)}catch(err){const body=q(`#${c.view} tbody`);if(body)body.innerHTML=`<tr><td class="empty">${esc(err.message)}</td></tr>`}}
  function value(row,key,i){if(key==='__row')return fan(i+1);if(key==='__form')return formLabel(row);return row[key]??''}
  function visibleRows(scope){const c=CFG[scope],s=data[scope],keys=['__row',...c.fields.map(f=>f[0]),...(c.form?['__form']:[])],query=normalize(s.query).toLowerCase();return s.rows.map((row,i)=>({row,i})).filter(({row,i})=>(!query||keys.some(k=>normalize(value(row,k,i)).toLowerCase().includes(query)))&&keys.every((k,n)=>!s.filters[n]||String(value(row,k,i))===s.filters[n]))}
  function render(scope){
    const c=CFG[scope],s=data[scope],view=q(`#${c.view}`);if(!view)return;const labels=['ردیف',...c.fields.map(f=>f[1]),...(c.form?['فرم تحویلی']:[])],keys=['__row',...c.fields.map(f=>f[0]),...(c.form?['__form']:[])];
    q('thead',view).innerHTML=`<tr>${labels.map(l=>`<th>${esc(l)}<span class="vehicle-col-resize"></span></th>`).join('')}</tr><tr class="vehicle-filters">${keys.map((k,n)=>{const vals=[...new Set(s.rows.map((r,i)=>String(value(r,k,i))).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'fa'));return `<th><select data-filter="${n}"><option value="">همه</option>${vals.map(v=>`<option ${String(s.filters[n]||'')===v?'selected':''}>${esc(v)}</option>`).join('')}</select></th>`}).join('')}</tr>`;
    const rows=visibleRows(scope);q('tbody',view).innerHTML=rows.length?rows.map(({row,i})=>`<tr data-id="${row.id}" class="${String(s.selected)===String(row.id)?'vehicle-selected':''}"><td>${fan(i+1)}</td>${c.fields.map(([key])=>`<td>${esc(row[key]??'—')}</td>`).join('')}${c.form?`<td class="vehicle-form-status">${esc(formLabel(row))}</td>`:''}</tr>`).join(''):`<tr><td class="empty" colspan="${labels.length}">موردی برای نمایش وجود ندارد.</td></tr>`;
    updateButtons(scope);installResize(scope,labels);
  }
  function updateButtons(scope){const view=q(`#${CFG[scope].view}`),row=selectedRow(scope),picked=!!row;q('.vehicle-edit',view).disabled=!picked;q('.vehicle-delete',view).disabled=!picked;if(CFG[scope].form){q('.vehicle-upload',view).disabled=!picked;q('.vehicle-download',view).disabled=!row?.form_path}}
  function widthFor(l){if(l==='ردیف')return 68;if(l==='فرم تحویلی')return 190;if(l.includes('توضیحات')||l.includes('مدارک'))return 300;if(l.includes('نام ')||l.includes('علت'))return 250;if(l.includes('تاریخ')||l.includes('ساعت'))return 135;return 155}
  function installResize(scope,labels){const table=q(`table[data-scope="${scope}"]`),heads=qa('thead tr:first-child th',table);table.querySelector('colgroup')?.remove();const group=document.createElement('colgroup'),cols=heads.map(()=>group.appendChild(document.createElement('col')));table.prepend(group);const key=`bamco-vehicle-widths-${scope}-v2`,saved=JSON.parse(localStorage.getItem(key)||'{}'),widths=labels.map(l=>saved[l]||widthFor(l));const apply=()=>cols.forEach((c,i)=>c.style.width=`${widths[i]}px`);apply();heads.forEach((h,i)=>q('.vehicle-col-resize',h).onpointerdown=e=>{e.preventDefault();const start=e.clientX,initial=widths[i],move=x=>{widths[i]=Math.max(65,Math.min(650,initial+start-x.clientX));apply()},up=()=>{localStorage.setItem(key,JSON.stringify(Object.fromEntries(labels.map((l,n)=>[l,widths[n]]))));removeEventListener('pointermove',move);removeEventListener('pointerup',up)};addEventListener('pointermove',move);addEventListener('pointerup',up)})}
  async function removeRow(scope){const c=CFG[scope],row=selectedRow(scope);if(!row||!confirm('این ردیف برای همیشه حذف شود؟'))return;try{if(row.form_path)await removeStored(row.form_path).catch(()=>{});await api(`/rest/v1/${c.table}?id=eq.${encodeURIComponent(row.id)}`,{method:'DELETE',prefer:'return=minimal'});data[scope].selected=null;toast('ردیف حذف شد.');await load(scope)}catch(err){toast(err.message,true)}}
  const pathUrl=p=>String(p).split('/').map(encodeURIComponent).join('/');
  async function storageRequest(path,options={}){const res=await fetch(`${SB_URL}/storage/v1/object/${path}`,{...options,headers:{apikey:SB_KEY,Authorization:`Bearer ${state.token}`,...options.headers}});if(!res.ok){const x=await res.json().catch(()=>({}));throw new Error(x.message||x.error||'عملیات فایل انجام نشد.')}return res}
  const removeStored=path=>storageRequest(`vehicle-forms/${pathUrl(path)}`,{method:'DELETE'});
  function chooseForm(scope){uploadScope=scope;q('#vehicleFormInput').value='';q('#vehicleFormInput').click()}
  async function uploadForm(e){const file=e.target.files?.[0],scope=uploadScope,row=selectedRow(scope);uploadScope=null;if(!file||!row)return;if(file.size>20*1024*1024)return toast('حجم فرم نباید بیشتر از ۲۰ مگابایت باشد.',true);if(!['application/pdf','image/jpeg','image/png'].includes(file.type))return toast('فرم باید PDF، JPG یا PNG باشد.',true);const name=String(file.name).replace(/[^A-Za-z0-9._\-\u0600-\u06ff]+/g,'_').slice(-120),path=`permanent/${row.id}/${Date.now()}-${name}`;try{await storageRequest(`vehicle-forms/${pathUrl(path)}`,{method:'POST',headers:{'Content-Type':file.type,'x-upsert':'true'},body:file});const old=row.form_path;await update(CFG[scope].table,`id=eq.${row.id}`,{form_path:path,updated_at:new Date().toISOString()});if(old)await removeStored(old).catch(()=>{});toast('فرم رکورد در پایگاه‌داده ذخیره شد.');await load(scope)}catch(err){toast(err.message,true)}}
  async function downloadForm(scope){const row=selectedRow(scope);if(!row?.form_path)return;try{const res=await storageRequest(`authenticated/vehicle-forms/${pathUrl(row.form_path)}`),blob=await res.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=formLabel(row);document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}catch(err){toast(err.message,true)}}
  function sheetRows(workbook,c){const sheet=workbook.Sheets[c.sheet];if(!sheet)return null;const matrix=XLSX.utils.sheet_to_json(sheet,{header:1,raw:false,defval:''});if(!matrix.length)return[];const headers=matrix[0].map(normalize),positions=Object.fromEntries(headers.map((h,i)=>[h,i]));return matrix.slice(1).filter(r=>r.some(v=>normalize(v))).map(r=>{const out={};c.fields.forEach(([key,label,type])=>{let v=normalize(r[positions[normalize(label)]]??'');if(type==='number')v=v===''?null:Number(v.replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/,/g,''));out[key]=Number.isNaN(v)?null:(v||null)});return out})}
  async function importWorkbook(e){const file=e.target.files?.[0];e.target.value='';if(!file)return;if(!window.XLSX)return toast('کتابخانه خواندن اکسل بارگذاری نشده است؛ صفحه را تازه‌سازی کنید.',true);try{const workbook=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true});const permanent=sheetRows(workbook,CFG.vehiclePermanent),temporary=sheetRows(workbook,CFG.vehicleTemporary);if(permanent===null&&temporary===null)throw new Error('دو تب «تحویل و تحول دائم» و «تحویل تحول موقت» در فایل پیدا نشد.');const total=(permanent?.length||0)+(temporary?.length||0);if(!total)throw new Error('در دو تب خودرو هیچ ردیف اطلاعاتی وجود ندارد.');if(!confirm(`${fan(total)} ردیف از فایل خوانده شد. اطلاعات موجود حفظ و ردیف‌های جدید به پایگاه‌داده اضافه شوند؟`))return;if(permanent?.length)await insert('vehicle_permanent_records',permanent);if(temporary?.length)await insert('vehicle_temporary_records',temporary);toast(`${fan(total)} ردیف با موفقیت وارد پایگاه‌داده شد.`);await Promise.all([load('vehiclePermanent'),load('vehicleTemporary')])}catch(err){toast(err.message||'ورود فایل اکسل انجام نشد.',true)}}
  function bind(scope){const c=CFG[scope],view=q(`#${c.view}`);if(!view||view.dataset.vehicleBound)return;view.dataset.vehicleBound='1';mount(scope);q('.vehicle-import',view).onclick=()=>{q('#vehicleExcelInput').value='';q('#vehicleExcelInput').click()};q('.vehicle-add',view).onclick=()=>{data[scope].selected=null;openEditor(scope)};q('.vehicle-edit',view).onclick=()=>openEditor(scope);q('.vehicle-delete',view).onclick=()=>removeRow(scope);q('.vehicle-search',view).oninput=e=>{data[scope].query=e.target.value;render(scope)};q('thead',view).onchange=e=>{if(e.target.matches('[data-filter]')){data[scope].filters[Number(e.target.dataset.filter)]=e.target.value;render(scope)}};q('tbody',view).onclick=e=>{const row=e.target.closest('tr[data-id]');if(row){data[scope].selected=Number(row.dataset.id);render(scope)}};if(c.form){q('.vehicle-upload',view).onclick=()=>chooseForm(scope);q('.vehicle-download',view).onclick=()=>downloadForm(scope)};load(scope)}
  function init(){if(ready)return;const p=q('#vehiclePermanentView'),t=q('#vehicleTemporaryView');if(!p||!t)return;ready=true;addStyles();ensureInputs();bind('vehiclePermanent');bind('vehicleTemporary');document.addEventListener('click',e=>{const b=e.target.closest('#nav button[data-view="vehiclePermanent"],#nav button[data-view="vehicleTemporary"]');if(b)setTimeout(()=>load(b.dataset.view),0)},true)}
  function boot(){init();if(ready)return;const observer=new MutationObserver(()=>{init();if(ready)observer.disconnect()});observer.observe(document.body,{subtree:true,childList:true});setTimeout(init,1500)}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
